*/


-- ----------------------------------------------------------------------------
-- STEP 2: HUMAN DEBUGGED & CORRECTED QUERY (PRODUCTION READY)
-- ----------------------------------------------------------------------------

WITH qualifying_agents AS (
    -- Step 1: Pre-filter for completed deliveries, valid delivery times,
    -- and ensure the threshold of > 5 orders is met BEFORE ranking!
    SELECT 
        da.city,
        da.agent_id,
        da.agent_name,
        COUNT(o.order_id) AS completed_orders,
        ROUND(AVG(o.delivery_time_mins), 2) AS avg_delivery_time
    FROM cap_delivery_agents da
    INNER JOIN cap_orders o ON da.agent_id = o.agent_id
    WHERE o.order_status = 'Delivered' 
      AND o.delivery_time_mins IS NOT NULL
    GROUP BY da.city, da.agent_id, da.agent_name
    HAVING COUNT(o.order_id) > 5
),
ranked_qualifying_agents AS (
    -- Step 2: Rank ONLY agents that satisfied the qualifying threshold.
    -- Deterministic tie-breaker: if order counts tie, faster agent ranks ahead.
    SELECT 
        city,
        agent_id,
        agent_name,
        completed_orders,
        avg_delivery_time,
        DENSE_RANK() OVER (
            PARTITION BY city 
            ORDER BY completed_orders DESC, avg_delivery_time ASC
        ) AS agent_rank
    FROM qualifying_agents
)
-- Step 3: Select top 3 ranked agents per city, sorted alphabetically then by rank
SELECT 
    city,
    agent_id,
    agent_name,
    completed_orders,
    avg_delivery_time,
    agent_rank
FROM ranked_qualifying_agents
WHERE agent_rank <= 3
ORDER BY city ASC, agent_rank ASC;
